    private fun balances(){content.addView(btn("\uff0b \u8bb0\u5f55\u4f59\u989d",-1,46){balanceDialog(null)},margin(0,14,0,8));section("\u8d26\u6237\u4f59\u989d",null);val list=card(Color.WHITE,16);if(accounts.none{it.active})list.addView(empty("\u9996\u6b21\u4f7f\u7528\uff1a\u8bb0\u5f55\u5fae\u4fe1\u3001\u652f\u4ed8\u5b9d\u6216\u5176\u4ed6\u8d26\u6237\u4f59\u989d"))else accounts.filter{it.active}.forEach{a->list.addView(accountRow(a.name,latest(a.name)).apply{setOnClickListener{balanceDialog(a.name)}})};content.addView(list);section("\u533a\u95f4\u6bd4\u8f83",null);val start=edit("\u8d77\u59cb\u65e5\u671f","2026-07-24");val end=edit("\u7ed3\u675f\u65e5\u671f",today());val dates=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL};dates.addView(start,LinearLayout.LayoutParams(0,dp(56),1f));dates.addView(Space(this),LinearLayout.LayoutParams(dp(8),1));dates.addView(end,LinearLayout.LayoutParams(0,dp(56),1f));content.addView(dates);start.setOnClickListener{pick(start)};end.setOnClickListener{pick(end)};val result=tv("\u9009\u62e9\u65e5\u671f\u540e\uff0c\u6309\u8d26\u6237\u8ba1\u7b97\u51c0\u53d8\u5316",13,muted,false);content.addView(btn("\u6bd4\u8f83\u4f59\u989d\u53d8\u5316",-1,46){result.text=compare(start.text.toString(),end.text.toString())},margin(0,12,0,0));content.addView(result,margin(4,12,4,0))}
