    private fun planRow(p:Plan)=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL;setPadding(dp(14),dp(12),dp(14),dp(12));addView(tv(if(p.income)"↗" else "↘",18,if(p.income)green else red,true));val info=LinearLayout(this@MainActivity).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(12),0,0,0);layoutParams=LinearLayout.LayoutParams(0,-2,1f)};info.addView(tv(p.title,14,ink,true));info.addView(tv("\u6bcf\u6708 ${p.day} \u65e5 \u00b7 \u5df2\u542f\u7528",11,muted,false));addView(info);addView(tv((if(p.income)"+ " else "- ")+money(p.cents),14,if(p.income)green else red,true))}
    private fun stat(parent:LinearLayout,label:String,cents:Long,color:Int){val c=card(Color.WHITE,14);c.setPadding(dp(12),dp(12),dp(8),dp(12));c.layoutParams=LinearLayout.LayoutParams(0,dp(78),1f).apply{setMargins(0,0,dp(6),0)};c.addView(tv(label,11,muted,false));c.addView(tv(money(cents),14,color,true));parent.addView(c)};private fun section(label:String,action:(()->Unit)?){val r=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL};r.addView(tv(label,17,ink,true),LinearLayout.LayoutParams(0,-2,1f));if(action!=null)r.addView(btn("\u67e5\u770b\u5168\u90e8",-2,36,action));content.addView(r,margin(0,22,0,10))}
    private fun entryDialog(){val box=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(16),0,dp(16),0)};val type=Spinner(this);type.adapter=ArrayAdapter(this,android.R.layout.simple_spinner_dropdown_item,arrayOf("\u6536\u5165","\u652f\u51fa"));val amount=EditText(this).apply{hint="\u91d1\u989d\uff0c\u4f8b\u5982 0.07";inputType=8194};val name=EditText(this).apply{hint="\u9879\u76ee\u540d\u79f0"};val cat=EditText(this).apply{hint="\u5206\u7c7b\uff0c\u4f8b\u5982 \u9910\u996e"};val date=EditText(this).apply{setText(today());isFocusable=false;setOnClickListener{pick(this)}};box.addView(type);box.addView(amount);box.addView(name);box.addView(cat);box.addView(date);dialog("\u8bb0\u4e00\u7b14",box){if(name.text.isNullOrBlank()||amount.text.isNullOrBlank()){toast("\u8bf7\u586b\u5199\u9879\u76ee\u548c\u91d1\u989d");return@dialog};entries.add(Entry(date.text.toString(),name.text.toString(),cat.text.toString().ifBlank{"\u5176\u4ed6"},parse(amount.text.toString()),type.selectedItemPosition==0));save();page=Page.ENTRIES;render();toast("\u8bb0\u8d26\u6210\u529f")}}
    private fun balanceDialog(selected:String?){val box=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(16),0,dp(16),0)};val name=EditText(this).apply{hint="\u8d26\u6237\u540d\u79f0\uff0c\u4f8b\u5982 \u5fae\u4fe1";setText(selected.orEmpty())};val amount=EditText(this).apply{hint="\u4f59\u989d";inputType=8194};val date=EditText(this).apply{setText(today());isFocusable=false;setOnClickListener{pick(this)}};val note=EditText(this).apply{hint="\u5907\u6ce8\uff08\u53ef\u9009\uff09"};box.addView(name);box.addView(amount);box.addView(date);box.addView(note);dialog("\u8bb0\u5f55\u4f59\u989d",box){if(name.text.isNullOrBlank()||amount.text.isNullOrBlank()){toast("\u8bf7\u586b\u5199\u8d26\u6237\u548c\u4f59\u989d");return@dialog};val n=name.text.toString();if(accounts.none{it.name==n})accounts.add(Account(n));snapshots.add(Snapshot(date.text.toString(),n,parse(amount.text.toString()),note.text.toString()));save();page=Page.BALANCES;render();toast("\u4f59\u989d\u5feb\u7167\u5df2\u4fdd\u5b58")}}
    private fun planDialog(){val box=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(16),0,dp(16),0)};val type=Spinner(this);type.adapter=ArrayAdapter(this,android.R.layout.simple_spinner_dropdown_item,arrayOf("\u6536\u5165","\u652f\u51fa"));val name=EditText(this).apply{hint="\u9879\u76ee\u540d\u79f0"};val amount=EditText(this).apply{hint="\u9884\u8ba1\u91d1\u989d";inputType=8194};val day=EditText(this).apply{hint="\u6bcf\u6708\u53d1\u751f\u65e5";inputType=2};box.addView(type);box.addView(name);box.addView(amount);box.addView(day);dialog("\u65b0\u5efa\u56fa\u5b9a\u8ba1\u5212",box){if(name.text.isNullOrBlank()||amount.text.isNullOrBlank()){toast("\u8bf7\u586b\u5199\u9879\u76ee\u548c\u91d1\u989d");return@dialog};plans.add(Plan(name.text.toString(),day.text.toString().toIntOrNull()?.coerceIn(1,31)?:1,parse(amount.text.toString()),type.selectedItemPosition==0));save();render();toast("\u56fa\u5b9a\u8ba1\u5212\u5df2\u4fdd\u5b58")}}
    private fun exportDialog(){val box=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(16),0,dp(16),0)};val s=EditText(this).apply{hint="\u5f00\u59cb\u65e5\u671f";setText("2026-01-01");isFocusable=false;setOnClickListener{pick(this)}};val e=EditText(this).apply{hint="\u7ed3\u675f\u65e5\u671f";setText(today());isFocusable=false;setOnClickListener{pick(this)}};box.addView(s);box.addView(e);dialog("\u5bfc\u51fa Markdown",box){export(s.text.toString(),e.text.toString())}}
    private fun dialog(t:String,v:View,save:()->Unit){AlertDialog.Builder(this).setTitle(t).setView(v).setNegativeButton("\u53d6\u6d88",null).setPositiveButton("\u4fdd\u5b58"){_,_->save()}.show()}
    private fun export(start:String,end:String){val ins=entries.filter{it.date in start..end&&it.income};val outs=entries.filter{it.date in start..end&&!it.income};val sb=StringBuilder("# \u4e2a\u4eba\u8d22\u52a1\u62a5\u544a\\n\\n- \u7edf\u8ba1\u65f6\u95f4\uff1a$start \u81f3 $end\\n- \u8d27\u5e01\uff1aCNY\\n\\n## \u8d26\u6237\u4f59\u989d\u53d8\u5316\\n\\n| \u8d26\u6237 | \u8d77\u59cb\u4f59\u989d | \u7ed3\u675f\u4f59\u989d | \u51c0\u53d8\u5316 |\\n|---|---:|---:|---:|\\n");accounts.filter{it.active}.forEach{a->val s=snapshots.filter{x->x.account==a.name&&x.date<=start}.maxByOrNull{it.date};val e=snapshots.filter{x->x.account==a.name&&x.date<=end}.maxByOrNull{it.date};if(s!=null&&e!=null)sb.append("| ${a.name} | ${decimal(s.cents)} | ${decimal(e.cents)} | ${decimal(e.cents-s.cents)} |\\n")};sb.append("\\n## \u5b9e\u9645\u6536\u5165\\n\\n");ins.forEach{sb.append("- ${it.date} ${it.category} ${decimal(it.cents)}\\n")};sb.append("\\n## \u5b9e\u9645\u652f\u51fa\\n\\n");outs.forEach{sb.append("- ${it.date} ${it.category} ${decimal(it.cents)}\\n")};sb.append("\\n## \u6c47\u603b\\n\\n- \u5b9e\u9645\u6536\u5165\uff1a${decimal(ins.sumOf{it.cents})} \u5143\\n- \u5b9e\u9645\u652f\u51fa\uff1a${decimal(outs.sumOf{it.cents})} \u5143\\n- \u5b9e\u9645\u51c0\u6536\u652f\uff1a${decimal(ins.sumOf{it.cents}-outs.sumOf{it.cents})} \u5143\\n\\n> \u4f59\u989d\u53d8\u5316\u57fa\u4e8e\u5df2\u8bb0\u5f55\u7684\u4f59\u989d\u5feb\u7167\u3002\\n");pendingExport=sb.toString();startActivityForResult(Intent(Intent.ACTION_CREATE_DOCUMENT).apply{type="text/markdown";putExtra(Intent.EXTRA_TITLE,"ledgertrace-$start-to-$end.md")},9001)}
    override fun onActivityResult(r:Int,c:Int,d:Intent?){super.onActivityResult(r,c,d);if(r==9001&&c==RESULT_OK)d?.data?.let{contentResolver.openOutputStream(it)?.use{o->o.write(pendingExport.toByteArray())};toast("Markdown \u5df2\u5bfc\u51fa")}}
    private fun compare(start:String,end:String)=accounts.filter{it.active}.joinToString("\\n"){a->val s=snapshots.filter{x->x.account==a.name&&x.date<=start}.maxByOrNull{it.date};val e=snapshots.filter{x->x.account==a.name&&x.date<=end}.maxByOrNull{it.date};if(s==null||e==null)"${a.name}\uff1a\u6570\u636e\u4e0d\u8db3" else "${a.name}\uff1a${if(e.cents>=s.cents)"\u589e\u52a0" else "\u51cf\u5c11"} ${money(kotlin.math.abs(e.cents-s.cents))}"}
    private fun load(){fun a(k:String)=JSONArray(prefs.getString(k,"[]"));try{val x=a("accounts");for(i in 0 until x.length()){val o=x.getJSONObject(i);accounts.add(Account(o.getString("name"),o.optBoolean("active",true)))};val s=a("snapshots");for(i in 0 until s.length()){val o=s.getJSONObject(i);snapshots.add(Snapshot(o.getString("date"),o.getString("account"),o.getLong("cents"),o.optString("note")))};val t=a("entries");for(i in 0 until t.length()){val o=t.getJSONObject(i);entries.add(Entry(o.getString("date"),o.getString("title"),o.getString("category"),o.getLong("cents"),o.getBoolean("income")))};val p=a("plans");for(i in 0 until p.length()){val o=p.getJSONObject(i);plans.add(Plan(o.getString("title"),o.getInt("day"),o.getLong("cents"),o.getBoolean("income"),o.optBoolean("active",true)))}}catch(_:Exception){}}
    private fun save(){fun j(f:(JSONArray)->Unit)=JSONArray().also(f).toString();prefs.edit().putString("accounts",j{x->accounts.forEach{ x.put(JSONObject().put("name",it.name).put("active",it.active))}}).putString("snapshots",j{x->snapshots.forEach{ x.put(JSONObject().put("date",it.date).put("account",it.account).put("cents",it.cents).put("note",it.note))}}).putString("entries",j{x->entries.forEach{ x.put(JSONObject().put("date",it.date).put("title",it.title).put("category",it.category).put("cents",it.cents).put("income",it.income))}}).putString("plans",j{x->plans.forEach{ x.put(JSONObject().put("title",it.title).put("day",it.day).put("cents",it.cents).put("income",it.income).put("active",it.active))}}).apply()}
